sect1.para:
  Directives लाई file compile हुने क्रममै सम्हालिने भएकाले directive values का रूपमा केवल literals (अपरिवर्तनीय मान) मात्र दिन सकिन्छ। Variables र constants प्रयोग गर्न पाइँदैन। स्पष्ट पार्न:



<?php
// यो मान्य छ:
declare(ticks=1);

// यो अमान्य छ:
const TICK_VALUE = 1;
declare(ticks=TICK_VALUE);
?>

  declare construct लाई global scope मा पनि प्रयोग गर्न सकिन्छ, जसले त्यसपछिका सम्पूर्ण code लाई असर गर्छ (तर यदि declare भएको file लाई अर्को file मा include गरिएको छ भने यसले parent file लाई असर गर्दैन)।



<?php
// यी दुवै समान हुन्:

// तपाईँ यसरी लेख्न सक्नुहुन्छ:
declare(ticks=1) {
    // सम्पूर्ण script यहाँ
}

// वा यसरी लेख्न सक्नुहुन्छ:
declare(ticks=1);
// सम्पूर्ण script यहाँ
?>

para.example:
   Tick प्रयोगको उदाहरण


<?php

declare(ticks=1);

// प्रत्येक tick event मा कल हुने function
function tick_handler()
{
    echo "tick_handler() called\n";
}

register_tick_function('tick_handler'); // tick event उत्पन्न गर्छ

$a = 1; // tick event उत्पन्न गर्छ

if ($a > 0) {
    $a += 2; // tick event उत्पन्न गर्छ
    print $a . "\n"; // tick event उत्पन्न गर्छ
}
?>


  &example.outputs;


tick_handler() called
tick_handler() called
tick_handler() called
3
tick_handler() called

sect2.para:
    encoding directive प्रयोग गरेर script को encoding तोक्न सकिन्छ।

   Script का लागि encoding घोषणा गर्ने


<?php
declare(encoding='ISO-8859-1');
// code यहाँ
?>
